package in.pooja.point;
import android.app.*;import android.os.*;import android.webkit.*;import android.Manifest;import android.content.pm.PackageManager;
public class MainActivity extends Activity { WebView w; public void onCreate(Bundle b){super.onCreate(b); getWindow().setFlags(1024,1024); w=new WebView(this); WebSettings s=w.getSettings(); s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setDatabaseEnabled(true); s.setMediaPlaybackRequiresUserGesture(false); s.setGeolocationEnabled(true); w.setWebChromeClient(new WebChromeClient(){ public void onPermissionRequest(final PermissionRequest r){ runOnUiThread(()->{ if(Build.VERSION.SDK_INT<23 || checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED) r.grant(r.getResources()); else r.deny(); }); } public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback cb){ if(Build.VERSION.SDK_INT<23 || checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED || checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED) cb.invoke(origin,true,false); else cb.invoke(origin,false,false); }}); w.setWebViewClient(new WebViewClient()); if(Build.VERSION.SDK_INT>=23){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO,Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},1001);} w.loadUrl("https://www.amazon.in/"); setContentView(w);} @Override public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();} }